ZivonSim.register("b-06", {
  init: function (ctx) {
    ctx.g.fillStyle = "#EFE6B8";
  },
  draw: function (ctx) {
    var g = ctx.g;
    g.fillStyle = "#EFE6B8";
    g.fillRect(0, 0, ctx.width, ctx.height);
    var a = ctx.values.a || 0;
    var travel = 0.5 * a * ctx.t * ctx.t * 12;
    var x = 30 + Math.abs(travel) % (ctx.width - 60);
    g.fillStyle = "#1C1B18";
    g.beginPath();
    g.arc(x, ctx.height / 2, 10, 0, Math.PI * 2);
    g.fill();
    g.fillStyle = "#5A5748";
    g.font = "12px monospace";
    g.fillText("a = " + a + " m/s2", 12, 18);
  }
});
